from django.test import TestCase,override_settings
from django.urls import reverse
from budgetbuddy.tests.helpers import create_budget_via_form
from budgetbuddy.tests.test_dashboard import BudgetSetupViewTests
from pathlib import Path
import re
class ConfigurationDiagnostics(TestCase):
 @override_settings(GOOGLE_OAUTH_CONFIGURED=True)
 def test_guest_google_button_with_setting_enabled(self):
  t=BudgetSetupViewTests('test_empty_dashboard_shows_google_when_configured');t.client=self.client;t.test_empty_dashboard_shows_google_when_configured()
 @override_settings(GOOGLE_OAUTH_CONFIGURED=True)
 def test_login_google_button_with_setting_enabled(self):
  t=BudgetSetupViewTests('test_login_page_shows_google_option');t.client=self.client;t.test_login_page_shows_google_option()
 def test_service_worker_serves_current_declared_version(self):
  source=Path('/workspace/budgetbuddy/static/budgetbuddy/js/sw.js').read_text();version=re.search(r"SW_VERSION\s*=\s*'([^']+)'",source).group(1)
  response=self.client.get(reverse('service_worker'));self.assertEqual(response.status_code,200);self.assertContains(response,version)
 def test_weekly_filter_context_and_current_label(self):
  create_budget_via_form(self.client);response=self.client.get(reverse('dashboard'),{'period':'weekly'})
  self.assertEqual(response.context['period'],'weekly');self.assertEqual(response.context['period_choices']['weekly'],'This week');self.assertContains(response,'This week')

