from django.test import TestCase
from django.contrib.auth import get_user_model
from allauth.account.forms import SignupForm
class SignupFixtureRetest(TestCase):
 def test_user_fixture_includes_required_username(self):
  user=get_user_model().objects.create_user(username='synthetic-rerun',email='synthetic@example.com',password='synthetic-only-password')
  self.assertEqual(user.username,'synthetic-rerun')
 def test_signup_rejects_invalid_email(self):
  form=SignupForm(data={'email':'invalid-email','password1':'Syntheticonly123!','password2':'Syntheticonly123!'})
  self.assertFalse(form.is_valid());self.assertIn('email',form.errors)

