import sys,os,json,unittest
sys.path[:0]=['/workspace','/qa'];os.environ['DJANGO_SETTINGS_MODULE']='_qa_settings'
import django;django.setup()
from django.test.runner import DiscoverRunner
records=[]
class Result(unittest.TextTestResult):
 def addSuccess(self,test):super().addSuccess(test);records.append({'test':test.id(),'status':'passed'})
 def addFailure(self,test,err):super().addFailure(test,err);records.append({'test':test.id(),'status':'failed','detail':self._exc_info_to_string(err,test)})
 def addError(self,test,err):super().addError(test,err);records.append({'test':test.id(),'status':'error','detail':self._exc_info_to_string(err,test)})
 def addSkip(self,test,reason):super().addSkip(test,reason);records.append({'test':test.id(),'status':'skipped','reason':reason})
class Runner(unittest.TextTestRunner):
 resultclass=Result
class DjangoRunner(DiscoverRunner):
 test_runner=Runner
runner=DjangoRunner(verbosity=2,interactive=False);failures=runner.run_tests(['target_diagnostics.ConfigurationDiagnostics'])
print('RESULT_JSON:'+json.dumps({'tests_run':len(records),'failures':sum(x['status']=='failed' for x in records),'errors':sum(x['status']=='error' for x in records),'skipped':sum(x['status']=='skipped' for x in records),'records':records}))
sys.exit(bool(failures))
